import{_ as e,o as a,c as l,aN as r}from"./chunks/framework.D31DlcCL.js";const n="/img/research-nian-evolution.svg",f=JSON.parse('{"title":"中国古代“年”概念的起源、演变与仪式重构：基于文字学与考古学的实证研究","description":"本文系统梳理了从商周至明清时期“年”这一概念的起源与演变，结合甲骨卜辞、青铜铭文及出土文物，重构了春节从丰收祭祀向世俗庆典转型的完整历史脉络。","frontmatter":{"title":"中国古代“年”概念的起源、演变与仪式重构：基于文字学与考古学的实证研究","date":"2026-02-18T10:00:00.000Z","categories":["杂谈"],"tags":["春节起源","甲骨文","岁首庆典","历史考古"],"description":"本文系统梳理了从商周至明清时期“年”这一概念的起源与演变，结合甲骨卜辞、青铜铭文及出土文物，重构了春节从丰收祭祀向世俗庆典转型的完整历史脉络。","cover":"/img/research-nian-origin.svg","top_img":"/img/banner.svg"},"headers":[],"relativePath":"posts/research-origin-of-nian.md","filePath":"posts/research-origin-of-nian.md","lastUpdated":null}'),i={name:"posts/research-origin-of-nian.md"};function o(s,t,g,d,h,c){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="摘要-abstract" tabindex="-1">摘要 (Abstract) <a class="header-anchor" href="#摘要-abstract" aria-label="Permalink to &quot;摘要 (Abstract)&quot;">​</a></h1><p>春节（Ancient Chinese New Year），古称“元日”、“正旦”、“岁首”，作为中华文明中最重要的传统节日，其起源与演变深刻映射了中国古代从神权政治向世俗伦理社会转型的历史进程。本文基于甲骨文、金文等出土文献的字源考证，结合《尚书》、《周礼》、《礼记》等传世典籍及汉画像石等考古实物，系统论证了“年”这一概念最初源于上古农业社会的丰收庆典（Harvest Festival）。研究发现，春节的演变经历了三个关键阶段：商周时期的“腊祭与祈谷”（Sacrificial Rituals），秦汉时期的“元日朝会与历法确立”（State Ceremony），以及唐宋以降的“世俗狂欢与宗法伦理”（Secular Celebration）。通过对“岁”、“祀”、“年”三个核心概念的语义场分析，本文揭示了春节背后“顺天应时、报本反始”的深层文化逻辑。</p><p><strong>关键词</strong>：春节；年；甲骨文；丰收祭；元日朝会；仪式演变</p><hr><h1 id="第一章-引言-introduction" tabindex="-1">第一章 引言 (Introduction) <a class="header-anchor" href="#第一章-引言-introduction" aria-label="Permalink to &quot;第一章 引言 (Introduction)&quot;">​</a></h1><h2 id="_1-1-研究背景与意义" tabindex="-1">1.1 研究背景与意义 <a class="header-anchor" href="#_1-1-研究背景与意义" aria-label="Permalink to &quot;1.1 研究背景与意义&quot;">​</a></h2><p>“年”不仅是一个时间单位，更是一个文化符号。在现代社会，春节被视为阖家团圆、辞旧迎新的象征，但其原始面貌往往被后世的民俗传说（如“年兽”故事）所遮蔽。学术界关于春节的研究多集中于民俗学视角的习俗描述，而缺乏对“年”这一概念本身在早期文明中如何生成、定型并发生功能性转变的系统性考察。探究“年”的起源，实际上是在探究中国古代农业文明的时间观、宇宙观以及神人关系的演变。</p><h2 id="_1-2-研究方法与资料来源" tabindex="-1">1.2 研究方法与资料来源 <a class="header-anchor" href="#_1-2-研究方法与资料来源" aria-label="Permalink to &quot;1.2 研究方法与资料来源&quot;">​</a></h2><p>本文采用<strong>二重证据法</strong>（Double Evidence Method），即“纸上之材料”（传世文献）与“地下之新材料”（考古发现）相结合的研究路径。</p><ul><li><strong>文献资料</strong>：主要涉及《尚书·尧典》、《诗经·豳风·七月》、《周礼·春官》、《礼记·月令》、《史记·天官书》、《汉书·律历志》等。</li><li><strong>考古资料</strong>：殷墟甲骨卜辞（Oracle Bone Inscriptions）、西周青铜器铭文（Bronze Inscriptions）、汉代画像石（Han Dynasty Stone Reliefs）、居延汉简（Juyan Han Bamboo Slips）等。</li></ul><hr><h1 id="第二章-年-之原像-基于文字学的考证-etymological-analysis" tabindex="-1">第二章 “年”之原像：基于文字学的考证 (Etymological Analysis) <a class="header-anchor" href="#第二章-年-之原像-基于文字学的考证-etymological-analysis" aria-label="Permalink to &quot;第二章 “年”之原像：基于文字学的考证 (Etymological Analysis)&quot;">​</a></h1><p>在汉字文化圈中，表达“一年”这一时间周期的概念主要有三个：“年”、“岁”、“祀”。它们分别代表了三种不同的文化视角：农业收成、天象观测、祭祀周期。</p><h2 id="_2-1-年-禾谷成熟的欢歌" tabindex="-1">2.1 “年”：禾谷成熟的欢歌 <a class="header-anchor" href="#_2-1-年-禾谷成熟的欢歌" aria-label="Permalink to &quot;2.1 “年”：禾谷成熟的欢歌&quot;">​</a></h2><p>甲骨文中的“年”字（见图 2-1），是一个典型的会意字。</p><ul><li><strong>字形结构</strong>：上部为“禾”（<span class="ancient-char">禾</span>），象成熟下垂的谷穗；下部为“人”（<span class="ancient-char">人</span>）或“千”（<span class="ancient-char">千</span>，象人腿部）。</li><li><strong>本义解析</strong>：《说文解字》云：“<strong>年，谷熟也。从禾千声。</strong>”罗振玉在《增订殷墟书契考释》中指出：“<strong>卜辞中年字亦作秂，从禾从人，象人负禾之形。</strong>”</li><li><strong>语义演变</strong>：最初，“年”并非时间单位，而是指代“庄稼成熟”这一事件。商代甲骨卜辞中常有“<strong>受年</strong>”（获得丰收）、“<strong>求年</strong>”（祈求丰收）、“<strong>有年</strong>”（丰收）的记载。例如《合集》9636片：“<strong>贞：我受年？</strong>”（占卜：我们将获得丰收吗？）。当庄稼成熟的周期相对固定后，“年”才逐渐引申为时间单位。</li></ul><p><img src="'+n+'" alt="图 2-1：“年”字甲骨文至楷书演变"></p><h2 id="_2-2-岁-木星纪年的投影" tabindex="-1">2.2 “岁”：木星纪年的投影 <a class="header-anchor" href="#_2-2-岁-木星纪年的投影" aria-label="Permalink to &quot;2.2 “岁”：木星纪年的投影&quot;">​</a></h2><p>“岁”（Suì）字在甲骨文中写作<span class="ancient-char">戉</span>（Yuè），象一把斧钺。</p><ul><li><strong>天文背景</strong>：古人观测天象，发现木星（Jupiter）在天空中运行的轨迹非常有规律，约12年绕天一周。因此木星被称为“<strong>岁星</strong>”。</li><li><strong>语义转化</strong>：最初“岁”可能与割庄稼的工具（斧钺）有关（收割周期），后专指岁星运行的一个特定阶段。《尔雅·释天》：“<strong>载，岁也。夏曰岁，商曰祀，周曰年，唐虞曰载。</strong>”这反映了不同朝代对时间周期的不同称谓侧重。</li></ul><h2 id="_2-3-祀-神人契约的周期" tabindex="-1">2.3 “祀”：神人契约的周期 <a class="header-anchor" href="#_2-3-祀-神人契约的周期" aria-label="Permalink to &quot;2.3 “祀”：神人契约的周期&quot;">​</a></h2><p>“祀”（Sì）在商代是极为重要的时间单位。</p><ul><li><strong>字形含义</strong>：甲骨文“祀”字从“示”（神主牌位）从“巳”（子，或象征祭品）。</li><li><strong>商代历法</strong>：商人尚鬼，祭祀活动频繁且有严格的周期性（周祭）。一轮完整的周祭往往恰好是一年。因此，商代常称“年”为“祀”，如“<strong>唯王六祀</strong>”（在商王统治的第六年）。</li></ul><p><strong>小结</strong>：“年”源于农事，“岁”源于天文，“祀”源于宗教。三者最终合流，构成了中国古代“天人合一”的时间观念基础。</p><hr><h1 id="第三章-礼仪之变-历代岁首庆典的演进-evolution-of-rituals" tabindex="-1">第三章 礼仪之变：历代岁首庆典的演进 (Evolution of Rituals) <a class="header-anchor" href="#第三章-礼仪之变-历代岁首庆典的演进-evolution-of-rituals" aria-label="Permalink to &quot;第三章 礼仪之变：历代岁首庆典的演进 (Evolution of Rituals)&quot;">​</a></h1><p>从上古的神秘祭祀到后世的世俗欢庆，春节的演变史是一部中国社会史的缩影。</p><h2 id="_3-1-商周时期-腊祭与祈谷-the-sacrificial-era" tabindex="-1">3.1 商周时期：腊祭与祈谷 (The Sacrificial Era) <a class="header-anchor" href="#_3-1-商周时期-腊祭与祈谷-the-sacrificial-era" aria-label="Permalink to &quot;3.1 商周时期：腊祭与祈谷 (The Sacrificial Era)&quot;">​</a></h2><p>在商周时期，“年”的庆祝活动带有浓厚的巫术色彩，主要分为两个阶段：</p><ol><li><strong>季冬腊祭 (La Sacrifice)</strong>：在农历十二月（腊月），人们会猎取野兽，祭祀百神。《礼记·郊特牲》记载：“<strong>天子大蜡八。</strong>”（天子举行盛大的腊祭，祭祀八位神灵，包括先啬、司什、农、邮表畷等）。此时的仪式核心是<strong>报赛</strong>（回报神灵的恩赐）。</li><li><strong>孟春祈谷 (Grain Prayer)</strong>：在正月初一（或立春），天子要举行籍田礼，祈求上帝赐予来年丰收。</li></ol><p><strong>关键特征</strong>：恐惧与敬畏。人们通过血祭和牺牲，试图安抚自然神灵，确保生存。</p><h2 id="_3-2-秦汉时期-元日朝会与历法确立-the-institutional-era" tabindex="-1">3.2 秦汉时期：元日朝会与历法确立 (The Institutional Era) <a class="header-anchor" href="#_3-2-秦汉时期-元日朝会与历法确立-the-institutional-era" aria-label="Permalink to &quot;3.2 秦汉时期：元日朝会与历法确立 (The Institutional Era)&quot;">​</a></h2><p>秦汉是大一统帝国的形成期，春节从单纯的宗教祭祀转变为国家政治大典。</p><ul><li><strong>历法变革</strong>：秦代以十月为岁首（建亥）。汉武帝太初元年（公元前104年）颁布《<strong>太初历</strong>》，正式定夏历正月（建寅）为岁首。这一制度确立了后世春节的日期基准。</li><li><strong>元日朝会</strong>：正月初一，文武百官、藩属国使臣需向皇帝朝贺。这不仅是庆祝，更是确认君臣秩序、展示帝国威仪的政治仪式。《后汉书·礼仪志》详细记载了朝会的盛况。</li><li><strong>傩戏驱邪</strong>：汉代宫廷在岁末会举行盛大的“大傩”仪式，由方相氏率领十二神兽驱逐疫鬼。</li></ul><p><strong>关键特征</strong>：政治化与制度化。春节成为皇权合法性的展示舞台。</p><h2 id="_3-3-唐宋时期-世俗狂欢与文化造极-the-secular-era" tabindex="-1">3.3 唐宋时期：世俗狂欢与文化造极 (The Secular Era) <a class="header-anchor" href="#_3-3-唐宋时期-世俗狂欢与文化造极-the-secular-era" aria-label="Permalink to &quot;3.3 唐宋时期：世俗狂欢与文化造极 (The Secular Era)&quot;">​</a></h2><p>唐宋时期，随着城市经济的发展，春节逐渐褪去神秘色彩，演变为全民狂欢的节日。</p><ul><li><strong>守岁之风</strong>：唐太宗李世民《守岁》诗：“<strong>冬比利尽，春气始通。</strong>”证明皇室已流行守岁。</li><li><strong>爆竹革命</strong>：从烧竹子（爆竿）发展到火药爆竹。宋代孟元老《东京梦华录》记载了开封府春节期间“<strong>山棚灯球</strong>”、“<strong>火药烟火</strong>”的盛景。</li><li><strong>桃符换新</strong>：王安石《元日》：“<strong>千门万户瞳瞳日，总把新桃换旧符。</strong>”此时的桃符已具有了春联的雏形。</li></ul><p><strong>关键特征</strong>：娱乐化与平民化。节日重心从宫廷下移至民间。</p><h2 id="_3-4-明清时期-宗法伦理的强化-the-ethical-era" tabindex="-1">3.4 明清时期：宗法伦理的强化 (The Ethical Era) <a class="header-anchor" href="#_3-4-明清时期-宗法伦理的强化-the-ethical-era" aria-label="Permalink to &quot;3.4 明清时期：宗法伦理的强化 (The Ethical Era)&quot;">​</a></h2><p>明清时期，春节礼仪高度程式化，家族祭祀成为核心。</p><ul><li><strong>祭祖</strong>：春节期间，家族成员必须齐聚祠堂祭拜祖先。</li><li><strong>拜年礼仪</strong>：严格的长幼尊卑跪拜礼。</li><li><strong>接神</strong>：接灶神、接财神等民俗信仰极其繁盛。</li></ul><p><strong>关键特征</strong>：伦理化。春节成为强化家族凝聚力和宗法秩序的工具。</p><h2 id="_3-5-近现代转型-从-元旦-到-春节-的身份重构-modern-transformation" tabindex="-1">3.5 近现代转型：从“元旦”到“春节”的身份重构 (Modern Transformation) <a class="header-anchor" href="#_3-5-近现代转型-从-元旦-到-春节-的身份重构-modern-transformation" aria-label="Permalink to &quot;3.5 近现代转型：从“元旦”到“春节”的身份重构 (Modern Transformation)&quot;">​</a></h2><p>中国传统的“年”长期被称为“元旦”或“新年”。现代意义上的“春节”确立，经历了三次关键的制度变革。</p><ol><li><p><strong>民国初年：废旧历，定元旦（1912）</strong> 1912年1月1日，孙中山在南京就任临时大总统，发布《临时大总统改历改元通电》，宣布：“<strong>行夏正，所以顺农时；从西历，所以便统计</strong>。”正式废除旧历（农历），改用阳历（公历），并将公历1月1日定为“元旦”。然而，民间习惯根深蒂固，百姓仍坚持过农历新年，导致出现了“官方过元旦，民间过新年”的二元局面。</p></li><li><p><strong>袁世凯时期：春节定名（1914）</strong> 1914年1月，民国内务总长<strong>朱启虔</strong>鉴于民间习俗难改，向大总统<strong>袁世凯</strong>呈《定四季节假呈》，提议：“<strong>拟请定阴历元旦为春节，端午为夏节，中秋为秋节，冬至为冬节</strong>。”袁世凯批准了该提议。从此，农历正月初一正式被官方命名为“<strong>春节</strong>”，以区别于公历的“元旦”。这是“春节”一词作为节日名称的法律源头。</p></li><li><p><strong>新中国成立：双年节确立（1949）</strong> 1949年9月27日，<strong>中国人民政治协商会议第一届全体会议</strong>通过决议，中华人民共和国采用公元纪年。为了明确区分农历和公历两个体系，会议重申：公历1月1日称为“元旦”，农历正月初一称为“春节”。至此，中国现代“双年节”（Dual New Year）并存的节日格局正式确立。</p></li></ol><hr><h1 id="第四章-仪式功能演变时间轴-timeline-of-ritual-functions" tabindex="-1">第四章 仪式功能演变时间轴 (Timeline of Ritual Functions) <a class="header-anchor" href="#第四章-仪式功能演变时间轴-timeline-of-ritual-functions" aria-label="Permalink to &quot;第四章 仪式功能演变时间轴 (Timeline of Ritual Functions)&quot;">​</a></h1><p>为了更直观地呈现“年”的功能演变，本研究构建了如下时间轴模型：</p><table tabindex="0"><thead><tr><th style="text-align:left;">时期</th><th style="text-align:left;">核心概念</th><th style="text-align:left;">主要仪式</th><th style="text-align:left;">社会功能</th><th style="text-align:left;">关键词</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>新石器-夏</strong></td><td style="text-align:left;">岁（天文）</td><td style="text-align:left;">观象授时</td><td style="text-align:left;">确定农时</td><td style="text-align:left;">陶寺观象台</td></tr><tr><td style="text-align:left;"><strong>商</strong></td><td style="text-align:left;">祀（祭祀）</td><td style="text-align:left;">周祭、燎祭</td><td style="text-align:left;">沟通神鬼</td><td style="text-align:left;">贞人、甲骨</td></tr><tr><td style="text-align:left;"><strong>西周</strong></td><td style="text-align:left;">年（丰收）</td><td style="text-align:left;">腊祭、籍田</td><td style="text-align:left;">祈求丰收</td><td style="text-align:left;">礼乐制度</td></tr><tr><td style="text-align:left;"><strong>秦</strong></td><td style="text-align:left;">岁首（政治）</td><td style="text-align:left;">颛顼历庆典</td><td style="text-align:left;">宣示皇权</td><td style="text-align:left;">法家秩序</td></tr><tr><td style="text-align:left;"><strong>汉</strong></td><td style="text-align:left;">元日（正统）</td><td style="text-align:left;">太初历朝会</td><td style="text-align:left;">确立正统</td><td style="text-align:left;">儒家经学</td></tr><tr><td style="text-align:left;"><strong>唐宋</strong></td><td style="text-align:left;">春节（娱乐）</td><td style="text-align:left;">守岁、灯会</td><td style="text-align:left;">释放情感</td><td style="text-align:left;">诗词、火药</td></tr><tr><td style="text-align:left;"><strong>明清</strong></td><td style="text-align:left;">过年（伦理）</td><td style="text-align:left;">祭祖、拜年</td><td style="text-align:left;">维系宗族</td><td style="text-align:left;">家国同构</td></tr><tr><td style="text-align:left;"><strong>近现代</strong></td><td style="text-align:left;">春节（民俗）</td><td style="text-align:left;">双年节分流</td><td style="text-align:left;">文化认同</td><td style="text-align:left;">公历/农历并存</td></tr></tbody></table><hr><h1 id="第五章-考古实证与文献综述-archaeological-evidences" tabindex="-1">第五章 考古实证与文献综述 (Archaeological Evidences) <a class="header-anchor" href="#第五章-考古实证与文献综述-archaeological-evidences" aria-label="Permalink to &quot;第五章 考古实证与文献综述 (Archaeological Evidences)&quot;">​</a></h1><h2 id="_5-1-甲骨文中的-受年-记录" tabindex="-1">5.1 甲骨文中的“受年”记录 <a class="header-anchor" href="#_5-1-甲骨文中的-受年-记录" aria-label="Permalink to &quot;5.1 甲骨文中的“受年”记录&quot;">​</a></h2><p>在《甲骨文合集》中，关于“年”的卜辞多达数百条。</p><ul><li><strong>实证 1</strong>：《合集》24440片：“<strong>辛亥卜，贞：王其求年于河，燎三小牢，沉三牛？</strong>” <ul><li><strong>解读</strong>：商王向河神祈求丰收，采用了“燎”（焚烧）和“沉”（沉入水中）两种祭祀方式，祭品包括三套小牢（羊/猪）和三头牛。这证明了商代“年”的祭祀等级极高。</li></ul></li></ul><h2 id="_5-2-汉画像石中的-庖厨与百戏" tabindex="-1">5.2 汉画像石中的“庖厨与百戏” <a class="header-anchor" href="#_5-2-汉画像石中的-庖厨与百戏" aria-label="Permalink to &quot;5.2 汉画像石中的“庖厨与百戏”&quot;">​</a></h2><p>山东嘉祥武氏祠汉画像石、河南南阳汉画馆藏品中，大量出现了岁末年初的庆祝场景。</p><ul><li><strong>实证 2</strong>：南阳汉画《<strong>百戏图</strong>》。画面中有跳丸、倒立、吞刀等杂技表演，旁边还有建鼓、排箫伴奏。这印证了汉代春节期间“<strong>大傩</strong>”仪式后，民间进行的娱乐表演活动。</li><li><strong>实证 3</strong>：四川德阳出土的《<strong>庖厨图</strong>》。描绘了宰杀猪羊、烹饪宴席的忙碌场景，佐证了汉代岁首宴饮（吃年饭）的习俗。</li></ul><hr><h1 id="第六章-结论-conclusion" tabindex="-1">第六章 结论 (Conclusion) <a class="header-anchor" href="#第六章-结论-conclusion" aria-label="Permalink to &quot;第六章 结论 (Conclusion)&quot;">​</a></h1><p>通过对“年”字源的追溯及历代岁首礼仪的考察，本文得出以下结论：</p><ol><li><strong>“年”的本质是农业时间的契约</strong>。它最初不是一个抽象的时间刻度，而是人与自然（禾谷）之间关于成熟与收获的契约。</li><li><strong>春节演变是文明演进的镜像</strong>。从商周的“神本”到汉代的“国本”，再到唐宋明清的“人本”（娱乐与伦理），春节的每一次蜕变都对应着中国社会形态的重大转型。</li><li><strong>仪式是文化记忆的载体</strong>。虽然现代社会不再举行“大傩”或“籍田礼”，但贴春联（桃符孑遗）、放鞭炮（驱鬼孑遗）、吃年夜饭（腊祭孑遗）等习俗，依然顽强地保存着数千年前的文化基因。</li></ol><hr><h1 id="参考文献-references" tabindex="-1">参考文献 (References) <a class="header-anchor" href="#参考文献-references" aria-label="Permalink to &quot;参考文献 (References)&quot;">​</a></h1><ol><li>[汉] 许慎. 《说文解字》[M]. 北京: 中华书局, 1963.</li><li>[清] 孙诒让. 《契文举例》[M]. 济南: 齐鲁书社, 1988.</li><li>常建华. 《岁时节日里的中国》[M]. 北京: 中华书局, 2006.</li><li>萧放. 《岁时传统与现代生活》[M]. 北京: 中国社会科学出版社, 2010.</li><li>李零. 《中国方术考》[M]. 北京: 东方出版社, 2001.</li><li>中国社会科学院考古研究所. 《小屯南地甲骨》[R]. 北京: 中华书局, 1980.</li><li>陈梦家. 《殷墟卜辞综述》[M]. 北京: 科学出版社, 1956.</li><li>饶宗颐. 《殷代贞卜人物通考》[M]. 香港: 香港大学出版社, 1959.</li><li>张光直. 《商周青铜器与铭文的综合研究》[M]. 台北: 中央研究院历史语言研究所, 1973.</li><li>袁珂. 《中国神话传说词典》[M]. 上海: 上海辞书出版社, 1985.</li></ol>',65)])])}const p=e(i,[["render",o]]);export{f as __pageData,p as default};
